(1, '', 'New template', '', '2025-10-27 18:49:47', 'new', 0, 0, 0, 1, 0, 'composer_template', NULL, 2, '', '', '', NULL, 0, '', NULL, 0, 0, '', 0, 0, 0, 0, 0),
(2, '', 'Event', '<!DOCTYPE html>\n<html xmlns=\"https://www.w3.org/1999/xhtml\" xmlns:o=\"urn:schemas-microsoft-com:office:office\">\n<head>\n<title>{email_subject}</title>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n<meta name=\"format-detection\" content=\"address=no\">\n<meta name=\"format-detection\" content=\"telephone=no\">\n<meta name=\"format-detection\" content=\"email=no\">\n<meta name=\"x-apple-disable-message-reformatting\">\n<!--[if gte mso 9]><xml><o:OfficeDocumentSettings><o:AllowPNG/><o:PixelsPerInch>96</o:PixelsPerInch></o:OfficeDocumentSettings></xml><![endif]-->\n<style type=\"text/css\">\n#outlook a{padding:0;}\n.ReadMsgBody{width:100%;} .ExternalClass{width:100%;}\n.ExternalClass, .ExternalClass p, .ExternalClass span, .ExternalClass font, .ExternalClass td, .ExternalClass div {line-height: 100%;}\n\nbody { margin: 0; padding: 0; height: 100%!important; width: 100%!important; -webkit-text-size-adjust: 100%; -ms-text-size-adjust: 100%; mso-line-height-rule: exactly;}\ntable,td { border-collapse: collapse !important; mso-table-lspace: 0pt; mso-table-rspace: 0pt;}\nimg { border: 0; height: auto; line-height: 100%; outline: none; text-decoration: none; max-width: 100%!important; -ms-interpolation-mode: bicubic;}\nimg.aligncenter { display: block; margin: 0 auto;}\n/* TinyMCE of WP */\n.alignleft { float: left; margin: 7px 15px 7px 0px; }\n.alignright { float: right; margin: 7px 0px 7px 15px; }\n.aligncenter { display: block; margin-left: auto; margin-right: auto; }\n.screen-reader-text { display: none }\nfigcaption { display: block; }\n@media screen and (max-width: 525px) {\n    .wrapper { padding-left: px; padding-right: px; padding-bottom: px; padding-top: px;}\n    .m-d-block {display: block}\n    .m-d-none {display: none; visibility: hidden; color: transparent;}\n    .m-pb-1 { padding-bottom: 16px!important; }\n    .p-0 { padding: 0 !important; }\n    .pt-1, .padding-top-15 { padding-top: 15px!important; }\n    .pb-1, .padding-bottom-15 { padding-bottom: 15px!important; }\n    .dh { display: hidden }\n    .fs-90 {\n        font-size: 90%;\n    }\n    .responsive { width:100%!important; }\n    table.responsive { width:100%!important; float: none; display: table; padding-left: 0; padding-right: 0; }\n    table[class=\"responsive\"] { width:100%!important; float: none; display: table; padding-left: 0; padding-right: 0; }\n    img { max-width: 100%!important }\n    img[class=\"responsive\"] { max-width: 100%!important; }\n    /* \"width: auto\" restores the natural dimensions forced with attributes for Outlook */\n    .fluid { max-width: 100%!important; width: auto; }\n    img[class=\"fluid\"] { max-width: 100%!important; width: auto; }\n\n    .block { display: block; }\n\n    td[class=\"responsive\"]{width:100%!important; max-width: 100%!important; display: block; padding-left: 0 !important; padding-right: 0!important; float: none; }\n    td.responsive { width:100%!important; max-width: 100%!important; display: block; padding-left: 0 !important; padding-right: 0!important; float: none; }\n\n    td[class=\"section-padding-bottom-image\"]{\n        padding: 50px 15px 0 15px !important;\n    }\n    /* For grids */\n    .max-width-100 { max-width: 100%!important; }\n\n    /* Obsolete */\n    .tnp-grid-column {\n        max-width: 100%!important;\n    }\n\n}\n\n/* Custom CSS */\n/* End Custom CSS */\n\n\n/* Text */\n.text p {\n    margin: 0 0 15px 0 !important;\n}\n.text a {\n    color: #007bff;\n    text-decoration: none;\n}\n\n/* Last posts */\n@media (max-width: 525px) {\r\n    .posts-1-column {\r\n        width: 100%!important;\r\n    }\r\n    .posts-1-image {\r\n        width: 100%!important;\r\n        display: block;\r\n    }\r\n}\r\n\r\n\n\n/* Html */\n.html-td-global p {\r\n    font-family: Helvetica, Arial, sans-serif;\r\n    font-size: 16px;\r\n}\r\n\n</style>\n</head>\n<body style=\"margin: 0; padding: 0; line-height: normal; word-spacing: normal;\" dir=\"ltr\">\n\n<table cellpadding=\'0\' cellspacing=\'0\' border=\'0\' width=\'100%\' role=\'presentation\'>\n<tr>\n<td bgcolor=\'#ffffff\' valign=\'top\' class=\'wrapper\'><!-- tnp --><table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" align=\"center\" width=\"100%\" style=\"border-collapse: collapse; width: 100%;\" class=\"tnpc-row tnpc-row-block ui-sortable-handle\" data-id=\"heading\">\n<tbody><tr><td align=\"center\" style=\"padding: 0;\" class=\"edit-block\">\n<!--[if mso | IE]><table role=\"presentation\" border=\"0\" cellpadding=\"0\" align=\"center\" cellspacing=\"0\" width=\"600\"><tr><td width=\"600\" style=\"vertical-align:top;width:600px;\"><![endif]--><table role=\"presentation\" type=\"options\" data-json=\"\" class=\"tnpc-block-content\" border=\"0\" cellpadding=\"0\" align=\"center\" cellspacing=\"0\" width=\"100%\" style=\"border-collapse: separate !important; width: 100%!important; max-width: 600px!important\">\n<tbody><tr><td align=\"center\" style=\"text-align: center; line-height: normal !important; letter-spacing: normal; mso-line-height-rule: exactly; outline: none; padding: 15px 15px 15px 15px;background-color: #ffffff;\" bgcolor=\"#ffffff\"><table border=\"0\" cellspacing=\"0\" cellpadding=\"0\" width=\"100%\" role=\"presentation\">\n    <tbody><tr>\n        <td align=\"center\" valign=\"middle\" dir=\"ltr\">\n            <div style=\"font-size: 20px;font-family: Verdana, Geneva, sans-serif;font-weight: normal;color: #222222; padding: 0; line-height: 130% !important; letter-spacing: normal;\" role=\"heading\" aria-level=\"1\">UPCOMING EVENT</div>\n        </td>\n    </tr>\n</tbody></table></td></tr></tbody></table><!--[if mso | IE]></td></tr></table><![endif]--></td></tr></tbody></table><table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" align=\"center\" width=\"100%\" style=\"border-collapse: collapse; width: 100%;\" class=\