 loading=\"lazy\" role=\"img\"/></figure></div>\n<!-- /wp:uagb/image --></div>\n<!-- /wp:uagb/container --></div></div>\n<!-- /wp:uagb/container -->\n\n<!-- wp:uagb/container {\"block_id\":\"b73b02d3\",\"directionDesktop\":\"row\",\"alignItemsDesktop\":\"flex-start\",\"backgroundType\":\"color\",\"backgroundColor\":\"var(u002du002dast-global-color-4)\",\"topPaddingDesktop\":100,\"bottomPaddingDesktop\":100,\"leftPaddingDesktop\":40,\"rightPaddingDesktop\":40,\"topPaddingTablet\":64,\"bottomPaddingTablet\":64,\"leftPaddingTablet\":32,\"rightPaddingTablet\":32,\"topPaddingMobile\":64,\"bottomPaddingMobile\":64,\"leftPaddingMobile\":24,\"rightPaddingMobile\":24,\"paddingLink\":false,\"variationSelected\":true,\"rowGapMobile\":0,\"isBlockRootParent\":true,\"layout\":\"grid\",\"gridColumnDesktop\":[{\"default\":\"custom\",\"min\":{\"unit\":\"px\",\"value\":10},\"max\":{\"unit\":\"fr\",\"value\":1},\"custom\":{\"unit\":\"%\",\"value\":50}},{\"default\":\"custom\",\"min\":{\"unit\":\"px\",\"value\":10},\"max\":{\"unit\":\"fr\",\"value\":1},\"custom\":{\"unit\":\"%\",\"value\":50}}],\"gridColumnTablet\":[{\"default\":\"custom\",\"min\":{\"unit\":\"px\",\"value\":10},\"max\":{\"unit\":\"fr\",\"value\":1},\"custom\":{\"unit\":\"%\",\"value\":50}},{\"default\":\"custom\",\"min\":{\"unit\":\"px\",\"value\":10},\"max\":{\"unit\":\"fr\",\"value\":1},\"custom\":{\"unit\":\"%\",\"value\":50}}],\"gridAlignItemsDesktop\":\"start\",\"gridAlignItemsTablet\":\"start\",\"gridAlignContentDesktop\":\"start\",\"gridAlignContentTablet\":\"start\"} -->\n<div class=\"wp-block-uagb-container uagb-layout-grid uagb-block-b73b02d3 alignfull uagb-is-root-container\"><div class=\"uagb-container-inner-blocks-wrap\"><!-- wp:uagb/container {\"block_id\":\"68004fa2\",\"backgroundType\":\"color\",\"backgroundColor\":\"var(u002du002dast-global-color-5)\",\"topPaddingDesktop\":60,\"bottomPaddingDesktop\":60,\"leftPaddingDesktop\":60,\"rightPaddingDesktop\":60,\"topPaddingTablet\":30,\"bottomPaddingTablet\"